  tools.exec_command({cmd:"cat packages/doctest-php/guard.yaml\ncat packages/phpstan-guard-rules/deptrac.yaml\ncat packages/doctest-php/src/Doctest/Parser/Example.php\ncat packages/doctest-php/src/Doctest/Executor/ExpressionEvaluator.php",max_output_tokens:5000})
]); 
