        $copy = clone $document;
        self::assertSame($copy->node('/'), $copy->dom());
        $element = $copy->dom()->documentElement;
        self::assertInstanceOf(DOMElement::class, $element);
        $element->textContent = '2';
        self::assertStringContainsString('<count>1</count>', $document->encode());
